let data = msg.payload;

// Lấy dữ liệu cảm biến
let temperature = data.temperature;
let humidity = data.humidity;
let light = data.light;
let motion = data.motion;

// Kiểm tra nhiệt độ
let fan = false;

if (temperature >= 30) {
    fan = true;
}

// Kiểm tra ánh sáng + chuyển động
let lightStatus = false;

if (light < 100 && motion === true) {
    lightStatus = true;
}

// Tạo dữ liệu sau khi xử lý
msg.payload = {
    temperature: temperature,
    humidity: humidity,
    light: light,
    motion: motion,
    fan: fan,
    lightStatus: lightStatus
};

return msg;

msg.payload = [
    {
        temperature: Number(msg.payload.temperature),
        humidity: Number(msg.payload.humidity),
        light: Number(msg.payload.light),
        motion: msg.payload.motion ? 1 : 0
    },
    {
        location: "living_room"
    }
];

return msg;
